Lemma aconst_ok_high : forall lo hi, sh AIMG_TOP <= lo ->
  (hi <= 0x115000 \/ 0x67ed90 <= lo
   \/ (0x64bad0 <= lo /\ hi <= 0x65d458) \/ (0x65d4e8 <= lo /\ hi <= 0x67e858) \/ (0x67e860 <= lo /\ hi <= 0x67ed90)) ->   (* [comment removed for export] *)
