Lemma global_shadow_length : forall sz szrz, 0 <= sz -> 8 * nsh sz <= szrz ->
  Z.of_nat (length (global_shadow sz szrz)) = nsh sz + (szrz - 8 * nsh sz) / 8.
Proof.
  intros sz szrz H1 H2. unfold global_shadow, poison_bytes. rewrite length_app, repeat_length, Nat2Z.inj_add, shadow_of_length by lia.
  rewrite Z2Nat.id; [reflexivity|]. Z.div_mod_to_equations. lia.
Qed.

(* [comment removed for export] *)
Lemma aglobals_facts :
  Forall (fun g : Z * Z * Z => let '(beg, sz, szrz) := g in
     AIMG_LO <= beg /\ beg + szrz <= AIMG_TOP /\ 0 <= sz /\ 8 * nsh sz <= szrz /\ szrz mod 8 = 0 /\ beg mod 8 = 0) aglobals.
Proof.
  (* [comment removed for export] *)
  assert (CK : forallb (fun g : Z * Z * Z => let '(beg, sz, szrz) := g in
            (AIMG_LO <=? beg) && (beg + szrz <=? AIMG_TOP) && (0 <=? sz) && (8 * nsh sz <=? szrz) && (szrz mod 8 =? 0) && (beg mod 8 =? 0)) aglobals = true)
    by (vm_compute; reflexivity).
  apply Forall_forall. intros [[beg sz] szrz] IN. pose proof (proj1 (forallb_forall _ _) CK _ IN) as K. cbv beta iota in K.
  apply andb_prop in K as [K K6]. apply andb_prop in K as [K K5]. apply andb_prop in K as [K K4].
  apply andb_prop in K as [K K3]. apply andb_prop in K as [K1 K2].
  apply Z.leb_le in K1. apply Z.leb_le in K2. apply Z.leb_le in K3. apply Z.leb_le in K4. apply Z.eqb_eq in K5. apply Z.eqb_eq in K6.
  repeat split; assumption.
Qed.
Scheme kc__2 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.prod Sort Prop.

(* [comment removed for export] *)
Lemma ACONST_ext : forall m m',
  ACONST m ->
