(* [comment removed for export] *)
Fixpoint cidx (a : Z) (l : list (Z * list cell)) : nat :=
  match l with [] => O | (b, _) :: r => if Z.eqb a b then O else S (cidx a r) end.
Fixpoint gidx (a : Z) (l : list (Z * Z * Z)) : nat :=
  match l with [] => O | (b, _, _) :: r => if Z.eqb a b then O else S (gidx a r) end.
Ltac acell_in :=
  first [ lazymatch goal with |- In (?a, _) aconst_cells =>
            let k := eval vm_compute in (cidx a aconst_cells) in apply (nth_error_In aconst_cells k); reflexivity end
        | cbn; tauto ].
Ltac aglob_in :=
  first [ lazymatch goal with |- In (?a, _, _) aglobals =>
            let k := eval vm_compute in (gidx a aglobals) in apply (nth_error_In aglobals k); reflexivity end
        | cbn; tauto ].

Lemma ACONST_cell : forall m a cs, ACONST m -> In (a, cs) aconst_cells -> rw_cells asegs m a cs.
Proof. intros m a cs (C & _ & _) IN. exact (proj1 (Forall_forall _ _) C _ IN). Qed.

(* [comment removed for export] *)
Lemma ACONST_shbase : forall m, ACONST m ->
  rw_cells asegs m AGOT_SHBASE [C8 (wz ASHBASE_CELL)] /\ rw_cells asegs m ASHBASE_CELL [C8 (wz ASHADOW_BASE)].
Proof. intros m AC. split; (eapply ACONST_cell; [exact AC| acell_in]). Qed.

